import{_ as n,o as r,c as t,a3 as e}from"./chunks/framework.BvvarXmc.js";const s="/screenshots/mailing.png",i="/screenshots/sapras.png",c=JSON.parse('{"title":"Pembuatan Surat Otomatis & Inventaris Sarpras","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-admin/persuratan-sapras.md","filePath":"panduan-admin/persuratan-sapras.md","lastUpdated":null}'),l={name:"panduan-admin/persuratan-sapras.md"};function o(p,a,m,u,d,k){return r(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="pembuatan-surat-otomatis-inventaris-sarpras" tabindex="-1">Pembuatan Surat Otomatis &amp; Inventaris Sarpras <a class="header-anchor" href="#pembuatan-surat-otomatis-inventaris-sarpras" aria-label="Permalink to &quot;Pembuatan Surat Otomatis &amp; Inventaris Sarpras&quot;">​</a></h1><p>Aplikasi menyediakan modul persuratan digital terintegrasi untuk mencetak dokumen resmi sekolah, serta modul inventaris sarana dan prasarana (Sarpras).</p><hr><h2 id="_1-tampilan-persuratan-sekolah-mailing" tabindex="-1">1. Tampilan Persuratan Sekolah (Mailing) <a class="header-anchor" href="#_1-tampilan-persuratan-sekolah-mailing" aria-label="Permalink to &quot;1. Tampilan Persuratan Sekolah (Mailing)&quot;">​</a></h2><p><img src="'+s+'" alt="Persuratan Sekolah"></p><h3 id="alur-cetak-surat-keterangan-siswa-aktif" tabindex="-1">Alur Cetak Surat Keterangan Siswa Aktif: <a class="header-anchor" href="#alur-cetak-surat-keterangan-siswa-aktif" aria-label="Permalink to &quot;Alur Cetak Surat Keterangan Siswa Aktif:&quot;">​</a></h3><ol><li>Masuk ke menu <strong>Persuratan (Mailing)</strong> Klik <strong><code>+ Buat Surat Baru</code></strong>.</li><li>Pilih template: <strong>Surat Keterangan Aktif Belajar</strong>.</li><li>Cari nama siswa pada kolom pencarian.</li><li>Sistem otomatis mengisi biodata siswa, kelas berjalan, identitas orang tua, dan nomor surat otomatis.</li><li>Klik tombol <strong><code>Cetak PDF</code></strong> lengkap dengan kop sekolah, barcode tanda tangan, dan cap stempel digital.</li></ol><hr><h2 id="_2-tampilan-inventaris-sarana-prasarana-sarpras" tabindex="-1">2. Tampilan Inventaris Sarana &amp; Prasarana (Sarpras) <a class="header-anchor" href="#_2-tampilan-inventaris-sarana-prasarana-sarpras" aria-label="Permalink to &quot;2. Tampilan Inventaris Sarana &amp; Prasarana (Sarpras)&quot;">​</a></h2><p><img src="'+i+'" alt="Inventaris Sarpras"></p><h3 id="alur-pencatatan-barang-inventaris" tabindex="-1">Alur Pencatatan Barang Inventaris: <a class="header-anchor" href="#alur-pencatatan-barang-inventaris" aria-label="Permalink to &quot;Alur Pencatatan Barang Inventaris:&quot;">​</a></h3><ol><li>Masuk ke menu <strong>Sarpras (Assets)</strong> Klik <strong><code>+ Tambah Barang Inventaris</code></strong>.</li><li>Isi informasi aset: Nama Barang, Kategori (Elektronik, Meubel, Alat Laboratorium), Lokasi Ruangan, dan Kondisi (Baik / Rusak Ringan / Rusak Berat).</li><li>Klik <strong>Simpan Aset</strong>.</li><li>Anda dapat mencetak label stiker QR Code untuk ditempelkan pada barang guna memudahkan inventarisasi berkala (<em>stock opname</em>).</li></ol>',12)])])}const h=n(l,[["render",o]]);export{c as __pageData,h as default};
